fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    // We want to split `a` into two parts, left and right,
    // such that concatenating them gives back `a`.
    // Also, if `a.len() > 1`, each returned part must be strictly shorter.

    let n = a.len();

    // If length is 0 or 1, just return a and empty vector
    if n <= 1 {
        (a, Vec::new())
    } else {
        // Find a split point roughly in the middle
        let mid = n / 2;

        // split_off moves the tail after mid into a new Vec,
        // so left will keep [0..mid), right will have [mid..n)
        let mut left = a;
        let right = left.split_off(mid);

        (left, right)
    }
}